/// The per-run parameters [WiredAgentCore.buildAgentStack] needs to
/// construct the [Agent]. Pure data — the host's callbacks arrive as
/// fields, the builder owns the assembly.
final class AgentWiringSpec {
  final Model model;
  final String systemPrompt;
  final int maxEmptyRetries;

  /// gh-1577: the empty-hiccup retry budget, threaded next to
  /// [maxEmptyRetries] so the CLI and every host can tune it (the loop
  /// default is 3).
  final int emptyHiccupRetries;

  /// gh-1577: first backoff sleep between empty-hiccup retries (tests pin
  /// it to [Duration.zero]).
  final Duration emptyHiccupBaseDelay;

  /// gh-1577: cap on the exponential empty-hiccup backoff.
  final Duration emptyHiccupMaxBackoff;
  final void Function(Object error)? onRunIdleTimeout;
  final void Function()? onRunWatchdogPaused;
  final int? contextWindowCap;
  final StuckToolConfig? stuckTool;

  /// Foreground tool-call budget (issue #1786); `null` = the loop's
  /// defaults (600s budget, offer at B/2).
  final ForegroundCallBudgetConfig? foregroundCall;
  final bool wireDump;
  final OverWindowRelief? overWindowRelief;
  final ToolMisuseBreaker? toolMisuseBreaker;
  final MessageCapPolicy? messageCapPolicy;
  final MessageCapRelief? messageCapRelief;

  const AgentWiringSpec({
    required this.model,
    required this.systemPrompt,
    this.maxEmptyRetries = 1,
    this.emptyHiccupRetries = 3,
    this.emptyHiccupBaseDelay = const Duration(milliseconds: 500),
    this.emptyHiccupMaxBackoff = const Duration(milliseconds: 8000),
    this.onRunIdleTimeout,
    this.onRunWatchdogPaused,
    this.contextWindowCap,
    this.stuckTool,
    this.foregroundCall,
    this.wireDump = false,
    this.overWindowRelief,
    this.toolMisuseBreaker,
    this.messageCapPolicy,
    this.messageCapRelief,
  });
}

